/* EIP-4 token metadata codec — register encodings taken from
   EIP-0004 itself (ergoplatform/eips): R4/R5/R6 are Coll[Byte]
   constants (0x0e + VLQ length + UTF-8 bytes) holding the TEXT of
   name, description and decimals — the EIP's worked example is
   "USD" / "Nothing backed USD token" / "2" -> 0e03555344 /
   0e184e6f... / 0e0132 — and R7 asset types come from the EIP's
   table (0e020101 picture NFT, 0e02010f file attachments,
   0e020201 membership). All vectors cross-checked with an
   independent Python build BEFORE coding. The decoder also
   accepts the wild Int-constant R6 form (0x04 + zigzag VLQ). */
const eip4Usd = app.buildEip4Registers("USD", "Nothing backed USD token", "2", "");
check("eip4 encode matches the EIP's own example", eip4Usd.r4Hex === "0e03555344" && eip4Usd.r5Hex === "0e184e6f7468696e67206261636b65642055534420746f6b656e" && eip4Usd.r6Hex === "0e0132" && eip4Usd.r7Hex === null && eip4Usd.assetType === null);
check("eip4 encode decimals forms", app.buildEip4Registers("X", "", "0", "").r6Hex === "0e0130" && app.buildEip4Registers("X", "", "18", "").r6Hex === "0e023138" && app.buildEip4Registers("X", "", "9", "").r6Hex === "0e0139");
check("eip4 encode omits empty description", app.buildEip4Registers("X", "", "0", "").r5Hex === null);
check("eip4 encode unicode name is UTF-8", app.buildEip4Registers("Ergö", "", "0", "").r4Hex === "0e05457267c3b6");
check("eip4 encode long name uses two-byte VLQ length", app.buildEip4Registers("A".repeat(130), "", "0", "").r4Hex.startsWith("0e8201") && app.buildEip4Registers("A".repeat(130), "", "0", "").r4Hex.length === 266);
check("eip4 encode asset types", app.buildEip4Registers("X", "", "0", "picture").r7Hex === "0e020101" && app.buildEip4Registers("X", "", "0", "audio").r7Hex === "0e020102" && app.buildEip4Registers("X", "", "0", "video").r7Hex === "0e020103" && app.buildEip4Registers("X", "", "0", "collection").r7Hex === "0e020104" && app.buildEip4Registers("X", "", "0", "attachments").r7Hex === "0e02010f" && app.buildEip4Registers("X", "", "0", "membership").r7Hex === "0e020201" && app.buildEip4Registers("X", "", "0", "nft").r7Hex === "0e0101");
check("eip4 encode rejects junk", app.buildEip4Registers("", "", "2", "") === null && app.buildEip4Registers("X", "", "", "") === null && app.buildEip4Registers("X", "", "2.5", "") === null && app.buildEip4Registers("X", "", "-1", "") === null && app.buildEip4Registers("X", "", "02", "") === null && app.buildEip4Registers("X", "", "abc", "") === null && app.buildEip4Registers("X", "", "1000", "") === null && app.buildEip4Registers("X", "", "2", "bogus") === null && app.buildEip4Registers(null, null, null, null) === null);
const eip4Dec = app.decodeEip4Registers("0e03555344", "0e184e6f7468696e67206261636b65642055534420746f6b656e", "0e0132", "");
check("eip4 decode of the EIP's own example", eip4Dec.name === "USD" && eip4Dec.nameValidUtf8 === true && eip4Dec.description === "Nothing backed USD token" && eip4Dec.decimals === "2" && eip4Dec.decimalsForm === "string" && eip4Dec.assetType === null);
